#!/usr/bin/env bash
# Acadia-OS — per-repo validation gate (stack: kas).
# Generated by tools/validate/generate.sh. Edit freely afterwards.
#
#   quick   seconds. Static checks that need no Docker/bitbake: Makefile parse,
#           board configs, YAML, swupdate sync.
#   full    minutes. Adds BitBake metadata parse inside the KAS container.
#
# OS is the Yocto image build for RPi 5/CM4/CM5. Building the image takes a
# long time and needs Docker; the gate deliberately separates fast static
# checks (quick) from the container-backed metadata parse (full).
set -uo pipefail
# shellcheck source=lib/validate-lib.sh
source "$(dirname "${BASH_SOURCE[0]}")/lib/validate-lib.sh"

TIER="$(tier_or_die "${1:-quick}")"

# --- quick -----------------------------------------------------------------

assert "Makefile present" 'test -f Makefile'
assert "kas config present" 'test -f kas/common.yaml'
assert "rpi5 board config present" 'test -f kas/boards/rpi5.yaml'

check "Makefile parses" "make" 'make -pn >/dev/null 2>&1'
check "board configs have a MACHINE field" "" 'make check-board'
check "swupdate sync (pre/post-install drift)" "" 'make lint-swupdate-sync'

[ "$TIER" = "quick" ] && { report "$TIER"; exit $?; }

# --- full ------------------------------------------------------------------

check "BitBake metadata parse" "docker" 'make validate'

report "$TIER"
